mapper.select:
SELECT  FROM t_due_diligence_case
WHERE source_namespace = #{namespace} AND source_application_id = #{applicationId} AND source_submission_id = #{submissionId}
ORDER BY case_id

SELECT  FROM t_due_diligence_case
WHERE source_namespace = 'CCT_CLIENT_APPLICATION' AND role_type = 'CLIENT' AND source_application_id = #{applicationId}
ORDER BY round_no DESC, case_id DESC LIMIT 1

mapper.sql:
WHERE source_namespace = 'CCT_CLIENT_APPLICATION' AND role_type = 'CLIENT'
AND status = #{status}
AND qualification_type = #{qualificationType}
AND source_application_id = #{applicationId}
AND responsible_partner_id = #{responsiblePartnerId}
AND responsible_partner_id IS NULL
AND jurisdiction_code = #{jurisdictionCode}

mapper.update:
UPDATE t_due_diligence_case
SET status = #{toStatus}, active_slot = NULL, decision_time = #{now}, version = version + 1, update_time = #{now}
WHERE case_id = #{row.caseId} AND version = #{row.version} AND status = #{row.status}
